create.example:
const { Color, Vector3 } = kcds.math;

const barrelPreview = kcds.world.PropGhost.create(player, {
  model: 'beer_barrel',
  position: player.position,
  tint: new Color(0, 1, 0, 0.5),
});
barrelPreview.setPose(player.position.clone().add(new Vector3(0, 0, 2)));

getBounds.example:
// client
const box = ghost.getBounds();
if (box) {
  const height = box.max.z - box.min.z;
  kcds.ui.Hud.showNotification(`The tent stands ${height.toFixed(1)} m tall.`);
}

getBounds.exampleCs:
// client
var box = ghost.GetBounds();
if (box)
{
    var height = box["max"]["z"].AsNumber() - box["min"]["z"].AsNumber();
    Hud.ShowNotification($"The tent stands {height.ToString("F1")} m tall.");
}

